function runAnim($, requestId, key, columns, rows, build) {
  const id = [requestId, key, columns, rows, drawMode()].join('|')
  if (anims.get(key)?.id === id) return
  stopAnim(key)
  const timer = $.clock.every(FRAME_MS, () => {
    let cells
    try {
      cells = build()
    } catch (err) {
      return
