    void $.ui.blit({ requestId, key, cells }).then(result => {
      if (!result.deny) { denies = 0; return }
      denies += 1
      if (anims.get(key)?.timer === timer) { timer.cancel(); anims.delete(key) }
      if (denies <= 4) $.ui.invalidate('ui.render')
    }, () => {})
  })
